INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Shuttle', 'In Space Shuttle, the player can learn the history of the NASA''s Space Shuttle program including the Enterprise, Discovery, Atlantis, Columbia, Challenger and the Endeavor. Players can learn the history of them including the astronauts, their missions and the outcome of each mission. Players can also train astronauts, launching them into space and watch them complete their mission and put their well earned training to good use.' FROM games WHERE igdb_id = 4343 ON CONFLICT (game_id, language_code) DO NOTHING;
