INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('x-com-ufo-defense', 24, '1994-03-01', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobqqd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4vdz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-COM: UFO Defense', 'X-COM: UFO Defense is a strategy game that combines tactical combat with base management and global defense. Players lead an international organization tasked with defending Earth from an alien invasion. The game unfolds on two levels: a global view where players manage resources, research alien technology, and intercept UFOs, and a tactical combat mode where squad-based battles occur. Players recruit and train soldiers, build bases, and develop new weapons and equipment based on recovered alien technology. Missions involve turn-based combat against aliens in various environments, with permadeath adding tension to each engagement. As the alien threat escalates, players must balance research, defense, and offensive operations to protect Earth''s nations from panic and alien infiltration. X-COM: UFO Defense''s blend of strategic depth, tactical combat, and atmospheric tension creates a compelling gameplay experience in the face of a global alien threat.' FROM games WHERE igdb_id = 24 ON CONFLICT (game_id, language_code) DO NOTHING;
