INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fleet Defender: The F-14 Tomcat Simulation', 'Fleet Defender is the first flight simulator to accurately recreate carrier-based operations. Experience all the excitement of a catapult launch, realistic air-to-air combat and the challenge of landing on a pitching deck. You''ll be drawn into the high-stakes world of Navy''s top guns.' FROM games WHERE igdb_id = 17951 ON CONFLICT (game_id, language_code) DO NOTHING;
