INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Carnage', 'What kind of un-be-leev-ably ugly monster is this? Chunks of armor fly off as you pound its body. This beefed-up, maxed-out monstrosity has jetted across the cosmos to beat your brains out! But is it the alien? Or is it YOU?' FROM games WHERE igdb_id = 45883 ON CONFLICT (game_id, language_code) DO NOTHING;
