INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lords of the Realm', 'The year is 1268, the English throne lies empty, and power-hungry lords are ready to wage war for newfound power. Your people now look to you to lead them to glory and prosperity. Manage your lands, strike bargains, betray alliances and ultimately destroy your rivals in this classic combination of turn-based and real-time strategy, and become the undisputed Lord of the realm!
