INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aretha II: Ariel no Fushigi na Tabi', 'The game is a console-style RPG - you fight random enemies in turn-based combat viewed from first-person perspective. Enemies may attack you from the sides, and you should pay attention which enemy you face. A unique feature the game uses is the ability to get special items called "souls" after battles, and then to use them to forge your own armor.' FROM games WHERE igdb_id = 15896 ON CONFLICT (game_id, language_code) DO NOTHING;
