INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '5 In One Fun Pak', '5 in One Fun Pak features four board games and one dice game. The featured games are Chess, Checkers, Backgammon, Reversi and Yacht (using Yahtzee''s rules). You can select to play one player against the computer or two players. You can select you skill levels for most games from 1 (easiest) to 3 (hardest), although the Chess game has skills of 1 to 6 and Yacht has no skill selection.' FROM games WHERE igdb_id = 93568 ON CONFLICT (game_id, language_code) DO NOTHING;
