INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King''s Field', 'King''s Field is a first-person 3D RPG which takes place in the underground tomb of the kingdom of Verdite. The player takes the role of Jean who explores 3D dungeons all alone in this dark fantasy-world with his sword and magic spells. A lot of challenges await Jean. The player will gain a great sense of accomplishment when overcoming tough situations in the game.' FROM games WHERE igdb_id = 7422 ON CONFLICT (game_id, language_code) DO NOTHING;
