INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tinhead', 46593, '1994-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2u3p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arrk4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tinhead', 'Once there was peace in the Galaxy. Then the evil Grim Squidge stole all the stars, threatening to hurl the Galaxy into a horrible Cosmic Void. Who will save the stars before it''s too late? Tinhead, Defender of the Edge of the Galaxy of course! Lead, slide, hop, fly and shoot your way through the wacky worlds and super-tricky challenging levels as you guide Tinhead ti free the stars. Take on pesky spinning Krystals, relentless flying Saw-Sirs and hordes of mega-tough bosses. Grab radical power-ups and zany vehicles like Batteries, Hyper-Hoppers and Rocket Packs to help Tinhead through each weird, monster-jammed world. 4 tin-tillating worlds with 24 super challenging levels. Unique pause-and-scroll to see the action offscreen. 3-way shooting power to blast the baddies. Dozens of power-ups and hidden bonus areas.' FROM games WHERE igdb_id = 46593 ON CONFLICT (game_id, language_code) DO NOTHING;
