INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkstalkers: The Night Warriors', 'The DarkStalkers have been unleashed! All the creatures from your darkest dreams have materialized to wage an eternal war for domination of the night. The fate of all humanity rests on who wins this epic struggle. You control the power of your favorite supernatural monster to combine their special attacks and unique abilities in a head to head fighting challenge. It''s a fierce and brutal conflict for supremacy in the monster hit of the year!' FROM games WHERE igdb_id = 20009 ON CONFLICT (game_id, language_code) DO NOTHING;
