INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CRW : Metal Jacket', 'CRW Metal Jacket is a mecha strategy game set in futuristic Japan. You command a group of well-armed soldiers through a series of missions, from infiltrating a drug lord''s mansion to assassinating the leader of a coup. The game proceeds in real-time, but you can pause the action at any time to give orders for your soldiers to move or attack. Your units can pilot one of three specialized mechs: Attacker, Defender, or Sniper, and your squad leader Reiko has an exclusive Commander mech. Each mech has a special move in addition to attacking or defending, such as the Defender''s Search, which reveals a small area of the map from the fog of war.
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 127833 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
