INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Basketball: Dunk & Hoop', 'Dream Basketball: Dunk & Hoop is a basketball game from Human Entertainment that was released exclusively in Japan for the Super Famicom in late 1994. The player can choose between a regular match of basketball, featuring two baskets and teams of five, or a 3-on-3 mode which is focused on one basket. Up to five human players can join in on either mode, provided a multi-tap peripheral is available.
