INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anstoss', 'On The Ball is a soccer manager simulation that differentiates itself from the others by its novel emphasis on the psychological aspects of the game. The game gives you, as team manager, full control over not just the strategies but even on what kind of "pep talk" you can give during half-time and PR moves to enhance public perception. Choose the host country, and lead your team from Qualification to World Cup in World Cup Edition and lead your English team to win the championship in League Edition.' FROM games WHERE igdb_id = 37126 ON CONFLICT (game_id, language_code) DO NOTHING;
