INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Idainaru Son Goku Densetsu', 'Join Gohan as he shares with Goten the battles of their deceased father, Goku, along with other characters. Dragon Ball Z: Idainaru Son Goku Densetsu illustrates Goku''s seven greatest battles: fighting Mercenary Tao, challenging Tien Shinhan at the World Martial Arts Tournament, destroying King Piccolo, fighting Piccolo at the 23rd World Martial Arts Tournament, protecting Earth from Vegeta, saving Namek from Frieza, and sacrificing his life to save the world from Perfect Cell.' FROM games WHERE igdb_id = 37599 ON CONFLICT (game_id, language_code) DO NOTHING;
