INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Max', 'Monster Max is an isometric adventure video game developed by Rare and published by Titus Software for the Game Boy handheld game console. It was released in December 1994 in Europe and January 1995 in the United States. Monster Max was designed by Jon Ritman and Bernie Drummond and is very similar in both graphics and gameplay to Ritman and Drummond''s 1987 title Head over Heels. The game sold poorly but received very positive reviews from critics.' FROM games WHERE igdb_id = 18629 ON CONFLICT (game_id, language_code) DO NOTHING;
