INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'J.B. Harold: Blue Chicago Blues', 'J.B. Harold: Blue Chicago Blues provides an interactive cinematic experience with real actors and settings. Choices arise, advancing time and requiring astute planning for mystery-solving and time management. Following Murder Club, J.B. Harold investigates the murder of a woman in Chicago. A surprising turn occurs as a female detective probing the case is killed and staged as a suicide. J.B. Harold teams up with local police to uncover the truth.' FROM games WHERE igdb_id = 4308 ON CONFLICT (game_id, language_code) DO NOTHING;
