INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'John Madden Football', 'John Madden and the NFL team up to create a new version of John Madden Football, designed specifically for the 3DO Interactive Multiplayer. You get the proven gameplay of the best selling 16-bit football game of all time, all new digitized graphics, CD quality sound and over 100 authentic video highlights from NFL Films. So, suit up and experience the only game that delivers real NFL action!' FROM games WHERE igdb_id = 13240 ON CONFLICT (game_id, language_code) DO NOTHING;
