INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Earthworm Jim', 'A crow is chasing a worm named Jim while in outer space Psy-Crow is chasing a renegade ship. The ship''s captain has stolen an ultra-high-tech-indestructible-super-space-cyber-suit and Queen Slug-for-a-Butt has ordered Psy-Crow to get it, since it can make her more beautiful than Princess-What''s-Her-Name. Psy-Crow blasts the captain and the suit falls to Planet Earth.
