INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wing War', 'Wing War is an arcade combat flight simulator game developed by Sega AM1 and manufactured by Sega. Released exclusively to Japanese and American arcades in 1994, the game puts players in the cockpit of a variety of both historic and modern aircraft and pits them in an aerial dogfight with a second rival aircraft.' FROM games WHERE igdb_id = 131192 ON CONFLICT (game_id, language_code) DO NOTHING;
