INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Down the World: Mervil''s Ambition', 'Down the World: Mervil''s Ambition is a Final Fantasy IV-like role-playing video game where the player takes the role as Mervil as he tries to become the most successful man in his world. This game was released for the Super Famicom in the fourth quarter of 1994.
