INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Albert Odyssey 2: Jashin no Taidou', 'Albert Odyssey 2 is a tactical role-playing video game developed and published by Sunsoft for the Super Famicom and released in December 1994. It is the sequel to the original Albert Odyssey and retains many of the same gameplay and story elements while featuring enhanced graphics and battle features.
