INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Zeque Den', 'Three girls embark on a journey to defeat evil forces trying to take over the world. The red haired Rufu can use spirits and magical powers, Kairu is a fast and strong martial artist and Hamusu can use her incredible boxing skills and cute pink gloves. Each girl is associated with a different elemental spirit, namely Fire, Earth and Water.' FROM games WHERE igdb_id = 38215 ON CONFLICT (game_id, language_code) DO NOTHING;
