INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortal Kombat II', 'Mortal Kombat II is a fighting game originally developed by Midway for arcades in 1993. It serves as the second main installment in the Mortal Kombat franchise and follows the success of its predecessor by enhancing the gameplay and further developing the original game''s mythos. Mortal Kombat II introduces more varied finishing moves and several iconic characters, such as Kitana, Mileena, Kung Lao, the hidden character Noob Saibot, and the series'' recurring villain, Shao Kahn.' FROM games WHERE igdb_id = 1619 ON CONFLICT (game_id, language_code) DO NOTHING;
