INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('graduation', 71310, '1994-05-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cvqzjhpqmsu3jxhnqd6u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sccwam.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Graduation', 'Graduation is a Japanese anime "life-sim" game published in America by Mixx Entertainment, the company that would later become Tokyopop. This was said to be "The First Anime Game to hit American Shores". You take the role of a homeroom teacher who is given the responsibility of teaching five girls for their last year of high school in the hopes of making them better people. You determine their class schedules, do guidance counseling, interfere with their weekend plans, and occasionally take to the streets to make sure they''re not getting into trouble. Each of the girls has their own individual personality and problems, and the choices you make will determine whether they graduate from high school, what they do with their lives afterward, and whether or not they wind up hating your guts. Get them all into top colleges and your boss will praise your genius. If they all flunk or wind up wanting to marry you, you''ll obviously be fired.' FROM games WHERE igdb_id = 71310 ON CONFLICT (game_id, language_code) DO NOTHING;
