INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Checkered Flag', 'Get ready to burn rubber! Race for the Checkered Flag behind the wheel of a turbo-powered speedway racer in real-time, 3D-rendered action. Choose from 10 high-performance tracks and see the speedway from 6 distinct views. Alter features and attributes on your racer to improve your times or even change the weather conditions. Action is so intense and realistic you''ll swear you feel the wind in your hair as your tires screech around the curves. Keep your sweaty palms on the controller!' FROM games WHERE igdb_id = 40815 ON CONFLICT (game_id, language_code) DO NOTHING;
