INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sports Illustrated Championship Football & Baseball', 'A sports game licensed by the leading sports magazine, Sports Illustrated. The title features both football and baseball games. Choose to play a 16-game football season, complete with 90 different offensive players and full championship setup. Or you can hit the baseball diamond, pick from 28 different teams, and obliterate the competition with a variety of pitches and exciting drives and diving catches.' FROM games WHERE igdb_id = 38437 ON CONFLICT (game_id, language_code) DO NOTHING;
