INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('xak-iii-the-eternal-recurrence', 37606, '1994-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4mkm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7mgc.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xak III: The Eternal Recurrence', 'Ratok, a descendant of the Duel bloodline, receives a distress message from Farland Castle... For the longest time, the world has been split into three, fairy, demon, and human, mainly for the purposes of having the demons sealed off... Yet somehow, the demons have found a way to enter the human world to launch an invasion. One by one, the human world''s kingdoms fall to an unforgiving reign of terror. Ratok is informed of the situation by a dying man''s last breath after Farland Kingdom fell, its king slaughtered mercilessly. Thus begins Ratok''s journey to prevent the demons from realizing their dreams of conquest...
