INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taz in Escape From Mars', 'You play as Taz, the famous cartoon-character. Taz is captured by Marvin the Martian and transfered to his intergalactic Zoo! Now it is your job to aid Taz in his great escape from the Zoo-prison and also find a way back home to Earth. To make the escape a little easier, there are items placed here and there, such as cakes which make regain your health. You also find gas tanks, which you can eat and then breath fire.' FROM games WHERE igdb_id = 8065 ON CONFLICT (game_id, language_code) DO NOTHING;
