INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Animated Storybook: The Lion King', 'This game let''s you revisit Disney''s The Lion King in an interactive storybook format with a selection of scenes from the movie. Each scene has narrated text and the characters and landscapes can be interacted with to trigger short animations. It also features three minigames: Simba stalking Zazu, drawing picures in the stars, catching bugs for Timon.' FROM games WHERE igdb_id = 214616 ON CONFLICT (game_id, language_code) DO NOTHING;
