INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eco Fighters', 'Eco Fighters, known in Japan as Ultimate Ecology (アルティメット エコロジー?), is an arcade game released by Capcom on the CPS-2 arcade system board on December 1993. The game is a horizontal shooter, where the player controls a ship with a rotating gun. As suggested by both its titles, the game has an "eco-friendly" theme. It was also developed by the same team from two Mega Man arcade titles, The Power Battles and The Power Fighters.' FROM games WHERE igdb_id = 39358 ON CONFLICT (game_id, language_code) DO NOTHING;
