INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raccoon Rascal', 'The 11 year old Robby North and his friend Oscar live in Wisconsin. During fishing they hear a shoot. A racoon-mother was shot. Robby takes the baby of this racoon with him and cares for it. The boy names the racoon Rascal. Guide Rascal through puzzles and trouble and find Robby!' FROM games WHERE igdb_id = 38262 ON CONFLICT (game_id, language_code) DO NOTHING;
