INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Body Blows', 'A compilation of the original fighting game "Body Blows" and its sequel, available only for Amiga, "Body Blows Galactic". The game combines everything from its predecessors and adds more colors, improved graphics and music, more backgrounds and endings, giving the player a total of 22 characters (including the invincible Max and his true self, the Terminator T17) and many fixes.' FROM games WHERE igdb_id = 8495 ON CONFLICT (game_id, language_code) DO NOTHING;
