INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Itadaki Street 2: Neon Sign ha Bara Iro ni', 'Itadaki Street 2 is the second game in the Itadaki Street series, and the only entry on Super Famicom. It has 14 new boards and 1 returning board, as well as new features such as the casino. This was the first entry published by Enix, and the first to feature elements from the Dragon Quest series.' FROM games WHERE igdb_id = 38345 ON CONFLICT (game_id, language_code) DO NOTHING;
