INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ganbare Goemon 3: Shishijuurokubee no Karakuri Manjigatame', 'Third title in the Ganbare Goemon series of platform/adventure games which cast you as the heroic Goemon as he attempts to save feudal Japan from all sorts of wacky evildoers. This time around, a time-travelling machine threatens all of Japan and thus Goemon and co. must jump into the future to stop the machine.
