INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indiana Jones'' Greatest Adventures', 'Indiana Jones’ Greatest Adventures is a 1994 platform video game released for the Super Nintendo Entertainment System. It is a video game adaptation of the Indiana Jones films Raiders of the Lost Ark (1981), Indiana Jones and the Temple of Doom (1984), and Indiana Jones and the Last Crusade (1989). The game was developed by Factor 5 and published by JVC Musical Industries, Inc. The story is told through cutscenes and text and is mostly faithful to the movies. Its release coincided with that of Super Star Wars: Return of the Jedi, also released by JVC and LucasArts and in the same platform style as the Super Star Wars trilogy.
