INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('an-american-tail-fievel-goes-west', 2308, '1994-08-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fvj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6e3u.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'An American Tail: Fievel Goes West', 'Based on the movie by the same name, Fievel Goes West is a platform game featuring the young mouse Fievel Mousekewitz. After immigrating to overseas to America in the 1800s(?), the Mousekewitz family has moved out onto the open frontier of the wild west. With dreams of being a cowboy, Fievel soon makes friends and plays on the dusty streets imagining himself a great gunslinger. But all is not well as the villainous Cat R. Waul and his gang of cats (as well as other creatures) has plans to turn this place into an all-you-can-eat mouse buffet. It''s up to Fievel to get in the way of Cat''s plans with the help of the canine sheriff, Wylie Burp and his non-mouse eating cat pal, Tiger' FROM games WHERE igdb_id = 2308 ON CONFLICT (game_id, language_code) DO NOTHING;
