INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Traffic Department 2192', 'Traffic Department 2192 is a top down shooter game in which the player pilots a futuristic "hoverskid" about a war-torn city. The game emphasizes story, with cutscenes before each mission following the arc of troubled pilot Lt. Velasquez. There are three episodes containing twenty missions each, with varied mission objectives.' FROM games WHERE igdb_id = 23728 ON CONFLICT (game_id, language_code) DO NOTHING;
