INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tecmo Super Bowl II: Special Edition', 'Tecmo returns to the gridiron with this new version of Tecmo Super Bowl for 16-bit console systems. Play with real National Football League players and teams in this 2D, side-scrolling arcade game. All of the features from the 8-bit game remain intact, with brand new ones added for even more electronic football fun!' FROM games WHERE igdb_id = 46598 ON CONFLICT (game_id, language_code) DO NOTHING;
