INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokonyan! Henpokorin Adventure', 'Pokonyan! Henpokorin Adventure is a platformer game for the Super Famicom that was published by the Japanese TV and movie company Toho. It is based on the long-running anime TV show Pokonyan! which depicted on the adventures of a cat/tanuki hybrid who was able to change his shape with his mysterious "Henpokorin" power similar to the shapeshifting abilities of the mythical tanuki. It was licensed outside of Japan as Rocky Raccat!.' FROM games WHERE igdb_id = 135497 ON CONFLICT (game_id, language_code) DO NOTHING;
