INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ruffian', 'Ruffian is a video game developed by Moonstruck and published by Explosive-Software. The programmer behind the game was Robert Tomlinson. It was released in 1994 for the Commodore Amiga. The game is a multi-directional scrolling platformer and features 17 levels. Ruffian bears similarities to Rainbow Islands, although its levels are significantly longer.' FROM games WHERE igdb_id = 92858 ON CONFLICT (game_id, language_code) DO NOTHING;
