INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cardangels', 135161, '1994-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7xvh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8c9g.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cardangels', 'Cardangels is a card game in which the player takes the roles of the three friends, playing cards against young, attractive female opponents. Four types of card games are available: poker, blackjack, speed, and babanuki (a variant of old maid). A slot machine-like introduction determines which games are played against which opponents. The player can select the amount of rounds (minimum ten) needed to win a game and advance to the next opponent. The "free play" mode allows the player to choose the type of game actively, but the amount of available opponents is lower. There is no gambling in any of the games; points are awarded for combinations in poker and blackjack. The opponents undress after losing a game; however, they retain their underwear - there is no explicit nudity in the game.' FROM games WHERE igdb_id = 135161 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 135161 AND ge.slug = 'card-and-board-game' ON CONFLICT DO NOTHING;
