INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaze Kiri: Ninja Action', 'Kaze Kiri takes place in Feudal Japan where the kingdom princess Shizuhime is abducted by a group of mysterious ninjas. A feared swordsman called Kaze Kiri, hero of the game, is given the task to rescue the poor girl and restore order. Our ninja can can use a broad variety of fightings skills - he can run, jump, dash and slash without mercy anyone who gets in his way.' FROM games WHERE igdb_id = 37612 ON CONFLICT (game_id, language_code) DO NOTHING;
