INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batsugun: Special Version', 'A second edition, titled Batsugun Special Version, was showcased to attendees at the 1994 AOU Show in Japan but it was never officially released in arcades, as Toaplan slid into bankruptcy and this special version appeared on the secondary video game collecting market after the company vanished. The special version featured a number of changes compared to the original version including a much smaller hitbox, a shield protecting the player from one hit, more powerful bombs, new scoring items, and the addition of multiple loops of increasing difficulty after completing the initial loop, among other changes.' FROM games WHERE igdb_id = 140737 ON CONFLICT (game_id, language_code) DO NOTHING;
