INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strip Pot', 'An erotic variant of the classic "fruit machine" game. Instead of playing for money, winners are treated to full motion video clips of "five of Europe''s most beautiful girls" (as stated on the back of the game''s box) disrobing for the camera. The player''s goal is to successfully strip all five of the models without running out of credits. The more you win, the more they take off.' FROM games WHERE igdb_id = 13056 ON CONFLICT (game_id, language_code) DO NOTHING;
