INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Dragon', 'Crystal Dragon follows the same genre and setting as Dungeon Master. It revolves around two adventurers, both controlled by you, in search for a powerful artifact. It is now in the possession of an evil wizard who has lead his minions across the world to find it and slaughtered anyone in his way. Now you must seek out and destroy this wizard in order to prevent him using the true powers of the crystal.' FROM games WHERE igdb_id = 12019 ON CONFLICT (game_id, language_code) DO NOTHING;
