INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Emblem: Monshou no Nazo', 'Fire Emblem: Monshou no Nazo (translated as Fire Emblem: Mystery of the Emblem in Fire Emblem: Awakening) is a Japanese tactical role-playing game developed by Intelligent Systems and published by Nintendo. It is the third game in the Fire Emblem series and was released in Japan on January 21, 1994. It was the first Fire Emblem title for the Nintendo Super Famicom and the first twenty-four-megabit cartridge for the system. The game is divided into two distinct parts, or "books". Book One is a remake of the original Fire Emblem: Shadow Dragon and the Blade of Light, and Book Two is a continuation of events, following the same characters.' FROM games WHERE igdb_id = 1435 ON CONFLICT (game_id, language_code) DO NOTHING;
