INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lion King', 'The Lion King brings to life the majesty and mystery of Africa through the tale of Simba, a lion cub faced with the challenging transition to maturity. Believing himself to be responsible for his father''s death, Simba enters the wilderness - where he finds salvation with Pumbaa the warthog and Timon the meerkat, and his education begins.
