INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Heroes III: Shiroki Majo', 'The Legend of Heroes III: Shiroki Majo (The White Witch) follows the adventures of a young boy named Jurio on his quest to complete his warrior initiation rite by traveling to five shrines. The game is the third entry in Falcom''s long running RPG franchise and the first entry of the "Gargarv Trilogy" in the series. The White Witch was originally created for the NEC PC-98 on March 18, 1994 with several ports and remakes released in the future.' FROM games WHERE igdb_id = 105413 ON CONFLICT (game_id, language_code) DO NOTHING;
