INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Hunter: Roddy & Cathy', 'Top Hunter: Roddy & Cathy is a side-scrolling platform video game developed by SNK for its Neo Geo Arcade system, which was released in 1994. It was later released for Neo Geo CD, and much later for the Wii virtual console. The game has been re-reissued later in the SNK Arcade Classics Vol. 1 compilation, which was released on May 1, 2008.' FROM games WHERE igdb_id = 46520 ON CONFLICT (game_id, language_code) DO NOTHING;
