INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Club 3DO: Station Invasion', 'Club 3DO: Station Invasion is an educational game, presented as a game show and designed for children ages 7 to 14. Your job is to be the best producer at an all-kid television station. Choose from five hit shows: a sitcom, game show, talk show, soap opera and a mystery adventure. Solve the puzzles and challenges of each show to get higher ratings. The game provides a mix of computer graphics and live character video.' FROM games WHERE igdb_id = 38830 ON CONFLICT (game_id, language_code) DO NOTHING;
