INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soulstar', 'Soulstar for the Sega CD/Mega CD is a 3D shoot-''em up that combines several different types of gameplay into one game. Some levels in this game are on a fixed path, similar to Space Harrier or Star Fox. Other levels allow your space craft to hover freely around a 3D environment, and in other levels your craft transforms into a walker robot for close-up attacks.' FROM games WHERE igdb_id = 5453 ON CONFLICT (game_id, language_code) DO NOTHING;
