INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seifuku Densetsu Pretty Fighter', 'Seifuku Densetsu: Pretty Fighter is a versus fighting game. The game features only female characters: Marin Aoki, Jyuri Akasaka, Minami Midorikawa, Kris Shiratori, Ryouko Kiori (Oryou), Keiko Konno (Kei), Ai Momoyama and Yawara Yamabuki. Players fight in a best two out of three round match. Controls are similar to Street Fighter series - six buttons, three to punch, three to kick.' FROM games WHERE igdb_id = 42527 ON CONFLICT (game_id, language_code) DO NOTHING;
