INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amazing Sonic', 'Amazing Sonic is a 1994 LCD game distributed by Tomy, and part of the Pocket Arcade series. A pop-up lid must be lifted to play the game. The LCD is not backlit, and is hard to see without proper light. It is slightly hard to control since the directional pad is separated into two different sections, making the game hard to figure out without instructions. Sonic must navigate through 12 maze-like levels.' FROM games WHERE igdb_id = 198603 ON CONFLICT (game_id, language_code) DO NOTHING;
