INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sougou Kakutougi: Astral Bout 2 - The Total Fighters', 'Sougou Kakutougi: Astral Bout 2: The Total Fighters is the sequel to Sougou Kakutougi: Astral Bout and like that game features various martial arts experts competing, not unlike MMA. The game is based on a real-life Japanese martial arts TV promotion, Fighting Network Rings. The eight characters represent different martial arts, including wrestling, karate, boxing, Muay Thai and others.' FROM games WHERE igdb_id = 38296 ON CONFLICT (game_id, language_code) DO NOTHING;
