INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Welcome to Bodyland', 'A theme park where every ride teaches something new about the human body. Take an adventure through the body! There''s never been an amusement park quite like this before. Join Ricki, your tour guide, and her hilarious parrot companion, Hiccup, on an adventure through the Bodyland Theme Park. Fast-paced rides and challenging activities encourage kids to explore the park on their own and learn about the human body at the same time. For children aged 5-11 years.' FROM games WHERE igdb_id = 374020 ON CONFLICT (game_id, language_code) DO NOTHING;
