INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Bonkers: Wax Up!', 'In this platform game, the player controls Bonkers through several levels where he must find 7 pickle clues. By pressing the pause button, a compass is shown, with the number of remaining clues and the direction of the next one. Bonkers can run (by holding button 1), jump (button 2) , duck and slide (by running and pressing the opposite direction on the d-pad).
