INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wheel of Fortune: Deluxe Edition', 'Wheel of Fortune: Deluxe Edition is an updated sequel to its predecessor that features 4,000 different puzzles and the standard features of Wheel of Fortune such as the bonus round. It also has a digitized likeness of Vanna White along with her voice. There are also digitized photos of people that can be chosen to represent the player. Players can go up against friends or compete against the computer A.I.' FROM games WHERE igdb_id = 42424 ON CONFLICT (game_id, language_code) DO NOTHING;
