INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild Guns', 'Released in 1994, Wild Guns is a shooting gallery video game for the Super Nintendo Entertainment System, developed by Natsume. Its setting is a unique blend of the Wild West, steampunk, and science fiction. The narrative revolves around Annie and Clint, a bounty hunter duo on a quest for vengeance after Annie''s family is killed. Players can choose to control either Annie or Clint, navigating through the foreground, avoiding enemy fire, and taking down hostile robots in the background. This gameplay combines elements from third-person shooters and light gun games.' FROM games WHERE igdb_id = 1344 ON CONFLICT (game_id, language_code) DO NOTHING;
