INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Fire Pro Wrestling Special', 'In this Special Fire Pro, you are a rookie wrestler working his way up through the ranks. During the journey, you fall in love with the sister of a wrestler named Akira Saeha. The road to the championship bout is a struggle, with loss after loss, both inside and outside of the ring, including you accidentally killing your best friend during a match.' FROM games WHERE igdb_id = 38286 ON CONFLICT (game_id, language_code) DO NOTHING;
