INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lightbringer', 'Light Bringer (ライトブリンガー) , also known as Dungeon Magic, is a 1994 arcade game by Taito Corporation Japan and is also included in Taito Legends 2. Unlike most medieval/fantasy beat ''em ups, it featured an isometric viewing angle, some platforming (usually involving players stacking rocks or crates to climb on and jump to treasure chests), unusually large stylised sprites, and variable blood/gore settings.
