INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Journeyman Project: Turbo!', 'The Journeyman Project: Turbo! is a remaster of The Journeyman Project (1993), with decreased loading times and improved animation quality. The year is 2318. The place: the sky-born city of Caldoria. After a century of bitter struggle, humanity has finally learned to live in peace. In 2117 the Unified World was established. And humanity knew no more war.' FROM games WHERE igdb_id = 79931 ON CONFLICT (game_id, language_code) DO NOTHING;
