INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dolucky no A.League Soccer', 'The Wild Bears have issued at challenge, and the whole town is down with soccer. Neco Dolucky isn''t about to lay in the sun and sit this one out. He assembles his friends and enters his team, The Red Hot Doluckies, to challenge all on-comers to a heated battle.' FROM games WHERE igdb_id = 38208 ON CONFLICT (game_id, language_code) DO NOTHING;
