INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fortress of Dr. Radiaki', 'The Fortress of Dr. Radiaki is a thrilling first-person shooter adventure mixing carnage with a cutting edge sense of humor. You will confront scores of different adversaries, including sword wielding samurai, stealthy ninja warriors, robots with toasters for heads, mutated alligators and more. You must use all your wits to find your way through the cavernous fortress and defeat the Machiavellian designs of the horribly twisted Dr. Radiaki!' FROM games WHERE igdb_id = 78778 ON CONFLICT (game_id, language_code) DO NOTHING;
