INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loony Labyrinth', 'Loony Labyrinth is the 4th pinball simulator created by LittleWing. It has one table with classic proto-Greek mythological themes. As an explorer and later as the legendary hero Theseus, the objective is to first find and activate the time machine, and then go back to ancient times and defeat the Minotaur.' FROM games WHERE igdb_id = 122307 ON CONFLICT (game_id, language_code) DO NOTHING;
