INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aero the Acro-Bat 2', 'In the sequel to Aero the Acro-Bat you have to defeat evil industrialist Edgar Ektor once again. He is back and again with bad ideas, so you - in the role of Aero - have to find and destroy him before he carries out his diabolical "Plan B". Like in the last installment, you have to jump, escape lethal obstacles and progress in time. This game features more moves for Aero, more mechanisms to use and more items to collect.' FROM games WHERE igdb_id = 5349 ON CONFLICT (game_id, language_code) DO NOTHING;
