INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jungle no Ouja Tar-chan: Sekai Manyu Dai Kakutou no Maki', 'Ta-chan is the king of jungle. He was abandoned in savanna, and has been raised by a chimpanzee, Etekichi. He has a dearest wife, Jane who used to be a top model in New York, but now she looks…Anyway, to protect animals from poachers, Ta-chan is fighting against them with his disciple, Pedro, and a master of Chinese martial arts, Ryo.' FROM games WHERE igdb_id = 38313 ON CONFLICT (game_id, language_code) DO NOTHING;
