INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-sidekicks-2-the-world-championship', 100707, '1994-04-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co586m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3tw7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Sidekicks 2: The World Championship', 'Super Sidekicks 2: The World Championship is a 1994 soccer arcade video game developed and published by SNK. It is the second installment in the Super Sidekicks series and the third soccer game released for Neo Geo MVS, preceding the original Super Sidekicks (1992). Featuring an arcade-style approach to soccer as its predecessor, the game allows players to choose any of the available game modes with AI-controlled opponents or other human players with the team of their choosing. Its gameplay uses a simplified three-button configuration.' FROM games WHERE igdb_id = 100707 ON CONFLICT (game_id, language_code) DO NOTHING;
