INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ano Subarashii Bento wo 2-do 3-do', 'This bento-shop simulator has players take over a failing bento shop with the goal of dominating the local town corner. Players can make their own custom bento via drag-and-drop from the available ingredients, choose how to stock their store, or snoop around opponents'' stores to get a feel for their strategy. While normally played against the computer, a local multiplayer mode supports up to four players.' FROM games WHERE igdb_id = 336178 ON CONFLICT (game_id, language_code) DO NOTHING;
