INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RayForce', 'RayForce (released in western Arcades as "Gunlock") is a top-down shooter. There are seven levels to play, ranging from battles in the atmosphere of planets to battling over mountain ranges, each with their own standard huge bosses at the end of these levels. The player takes control of a starfighter called the RVA-818 X-LAY, out to destroy any opposing forces.' FROM games WHERE igdb_id = 22349 ON CONFLICT (game_id, language_code) DO NOTHING;
