INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Popeye', 'Popeye: Ijiwaru Majo Seahag no Maki is a board game and sidescroller action game in one. The goal is to recover all the hearts scattered around the game board and defeat any mini-bosses presented by Popeye villains, and then finally defeat the seahag.
