INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Warriors', 'Ninja Warriors plays as a side scrolling beat ''em up, and is a single player adaptation of The Ninja Warriors arcade game. Players can choose from 3 different Ninja Warriors: Ninja, Kunoichi or Kamaitachi. The characters play differently, but share some common controls. Each can attack, jump, grab the enemy, block attacks or unleash a special attack on the entire screen. This special attack charges up gradually and can be reset by being knocked to the ground.' FROM games WHERE igdb_id = 42654 ON CONFLICT (game_id, language_code) DO NOTHING;
