INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Romance of the Three Kingdoms IV: Wall of Fire', 'The Three Kingdoms era of Chinese history is the setting for this strategic war game. Select one of 38 leaders and guide your people to power by military or diplomatic means in an isometrically viewed world. Military tactics such as well-placed taunts and deliberate enemy confusion are on offer. Weaponry includes catapults and automatic-firing crossbows.' FROM games WHERE igdb_id = 7040 ON CONFLICT (game_id, language_code) DO NOTHING;
