INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Horde', 'The Horde is a hybrid action-strategy video game that was originally released for 3DO and was ported to the Sega Saturn and DOS. It also featured full-motion video sequences featuring a number of actors including Kirk Cameron as Chauncey and Michael Gregory as Kronus Maelor. Video sequences were reduced to slide shows (with full sound) in some versions.
