INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('heracles-no-eikou-iv-kamigami-kara-no-okurimono', 42291, '1994-11-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4c1f.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heracles no Eikou IV: Kamigami kara no Okurimono', 'You join your friends Plato and Epipha from the mythical city of Atlantis. Their fine professor has been researching possibilities of ever lasting life. Soon after the game begins, an event happens that transcends life as they know it. You will encounter life, death, Pandora’s Box, Heracles, and even the gods themselves! You must unravel the mystery of what happened. You must help Heracles in his quest too. You will travel by boat, saba, submarine, and even on the legendary Pegasus! You will journey to the underworld, under the sea, and even to the heavens above! The Glory of Heracles awaits you!' FROM games WHERE igdb_id = 42291 ON CONFLICT (game_id, language_code) DO NOTHING;
