INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('donkey-kong--2', 1089, '1994-06-14', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wd9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1gg6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong', 'Donkey Kong is a Game Boy game which starts out with the premise of being a straight remake of the original Donkey Kong arcade game. Although at first it appears to be just a port, the familiar levels from the arcade game are just a prelude to the real platform jumping adventure. There are 96 levels spread out over 12 worlds. These levels are much more complex than the originals, featuring scrolling backgrounds, numerous objects to collect, and enemies to avoid. Along the way, you will encounter several boss style battles with Donkey Kong, as well. When played on a Super Game Boy, the game is colorized, digitized speech is added and the ending music takes advantage of the SNES sound chip.' FROM games WHERE igdb_id = 1089 ON CONFLICT (game_id, language_code) DO NOTHING;
