INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Goku Hishou-den', 'Dragon Ball Z: Goku Hishou-den is a RPG/Strategy oriented game, as the player chooses when to move, charge energy, punch, kick, or do any number of different special attacks, then watches as the events take place. The player must take an active part in dodging attacks by pressing appropriate buttons at just the right moments.' FROM games WHERE igdb_id = 49103 ON CONFLICT (game_id, language_code) DO NOTHING;
