INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wacky Wheels', 'Nothing beats the excitement of playing against other human racers, and in Wacky Wheels, you can do just that. You and a friend can play at the same computer or you can race against challenging computer opponents who have adjustable degrees of difficulty. Either way, Wacky Wheels is packed with the features you want: non-stop action and variety, heart-racing music and furious 3D point-of-view vivid VGA graphics and animations. It''s so fun, you''ll hate to finish.' FROM games WHERE igdb_id = 8880 ON CONFLICT (game_id, language_code) DO NOTHING;
