INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('return-to-ringworld', 46733, '1994-05-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/zhcm7ygmoqcbn9ie2h28.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Return to Ringworld', 'After saving the puppeteer race from extermination and uncovering some powerful ancient technology in the first game, Quinn, Seeker of Vengeance and Miranda Rees find themselves searched as fugitives by all three major species, so they go to Ringworld to hide. Once in Ringworld they''ll try to uncover some evidence to clear their names, but they stumble across another universe-threatening plot. This time U.N. general Carson Teal is out to rule the universe by uncovering Ringworld''s secrets, and you must stop him.
