INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Götzendiener', 'Götzendiener, made by the creators of Princess Maker, presents its own take on "rescue the princess" story: here, there is nobody who can rescue the princess but herself. Armed with the sword, the princess must explore the isometric dungeon, fighting enemies in real-time combat and solving environmental puzzles on the way. The princess jumps automatically, and the actions in the game are limited to attacking enemies with a sword and pushing and pulling objects.' FROM games WHERE igdb_id = 19661 ON CONFLICT (game_id, language_code) DO NOTHING;
