INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Dangerous Creatures', 'Dangerous Creatures allows the user to investigate animals according to several categories: Atlas (animals by country), Weapons (animals that had teeth, venom, or claws), Guides (related animals), Habitats (animals from a given environment), and Index (an alphabetical list of all animals covered). Animal articles have pictures, descriptions, and video clips. In addition a user can be tested with quizzes on the animals.' FROM games WHERE igdb_id = 311960 ON CONFLICT (game_id, language_code) DO NOTHING;
