INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Micropede', 'Micropede is a fast-paced arcade-style shooter inspired by classics like Centipede and Millipede. Players control a character using a mouse, navigating through increasingly difficult levels while shooting segmented enemies and avoiding contact with hostile creatures. The game features 500 levels, each filled with micropede segments and other enemies such as spiders, mosquitoes, dragonflies, bees, and beetles' FROM games WHERE igdb_id = 14504 ON CONFLICT (game_id, language_code) DO NOTHING;
