INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ToonTime... In the Classroom', 'Cartoons are more fun than ever! ToonTime provides multimedia entertainment for children, as well as adults who are still young at heart. ToonTime... In the Classroom brings to your television a whole new method of interactivity never before available. Select randomly from six classic full color cartoons: Tweety, Bugs Bunny, Daffy Duck, Popeye, Elmer Fudd and Superman, and play the chosen cartoon immediately (no more rewinding a videotape). Have fun manipulating the digitized cartoons by shrinking, enlarging, twisting and distorting them inside a classroom. Have more fun playing the cartoons on different classroom objects. Reshape and distort the objects as they bounce around the classroom.' FROM games WHERE igdb_id = 37229 ON CONFLICT (game_id, language_code) DO NOTHING;
