INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Norimono Banzai!!: Kuruma Daishuugou!!', 'Norimono Banzai!! Kuruma Daishūgō!! (のりものばんざい！！ くるま大集合！！) is a CD-ROM-based educational title for the Playdia console. The title roughly translates to "Vehicles Banzai!! Big Car Set!!"' FROM games WHERE igdb_id = 63957 ON CONFLICT (game_id, language_code) DO NOTHING;
