INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Riddle of the Maze', 'The Riddle of the Maze is a digital adaptation of the 1985 puzzle book "Maze: Solve the World''s Most Challenging Puzzle" by Christopher Manson. The player begins outside a building. The building is a labyrinth that comprises of various rooms. Each room is connected with different rooms through various doors. The goal is to complete the maze with the shortest path and solve the Riddle.' FROM games WHERE igdb_id = 138449 ON CONFLICT (game_id, language_code) DO NOTHING;
