INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nekketsu Oyako: Hot Blooded Family', 'Middle-aged housewife Saeko Hibino has a secret: she''s actually a Nobel laureate theoretical physicist who devised a completely new type of antimatter fusion reactor at only 17 years old. But when a band of no-good bad guys calling themselves the Haraguro-dan find out, they figure she''s perfect to help them complete their ultimate secret doomsday weapon and kidnap her. Her family aren''t going to take this lying down, though, and immediately take up arms, setting out to free her by whatever means necessary!' FROM games WHERE igdb_id = 44807 ON CONFLICT (game_id, language_code) DO NOTHING;
