INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Geograph Seal', 'Exact''s Geograph Seal, released for the Sharp X68000 computer in 1994, is a precursor to Jumping Flash! Rendered in 3D polygons, it was the earliest first-person shooter with platforming mechanics. It also allowed the player to aim the weapon, and took place in free-roaming outdoor environments rather than the corridor labyrinths of contemporary FPS games like Doom.' FROM games WHERE igdb_id = 63819 ON CONFLICT (game_id, language_code) DO NOTHING;
