INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'YuYu Hakusho 2: Kakutou no Sho', 'The second of four Namco Super Famicom adaptations of the YuYu Hakusho manga and anime, featuring the delinquent student Yusuke who becomes a spirit world investigator after he passes away. While its predecessor, YuYu Hakusho, featured a combat system that was turn-based and tactical, Kakutou no Sho is instead a standard example of the four-button fighter game model that became popular after the success of Capcom''s Street Fighter II.' FROM games WHERE igdb_id = 42530 ON CONFLICT (game_id, language_code) DO NOTHING;
