INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yume Utsutsu Dreamy', 'One day Naoki picks up a mysterious pendant hanging on a telephone pole on the way back from school. On that night two fairies came to his dream saying that an angel could return to the original world if Naoki could make some girls happy during the next ten days. He decides to sleep as much as possible during next ten days and girls start to come to his dreams...' FROM games WHERE igdb_id = 247507 ON CONFLICT (game_id, language_code) DO NOTHING;
