INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wrath of the Gods', 'Wrath of the Gods is a point & click adventure game created by Luminaria for the PC and was developed to help students understand Greek Mythology. Wrath of the Gods sees the player walk in the footsteps of ancient Greek heroes like Theseus, Jason & Hercules, facing up against creatures of legend & meeting the Gods. Despite being a game designed as a teachers aide, Wrath of the Gods still manages to be an engaging and enjoyable point & click adventure for gamers of all ages.' FROM games WHERE igdb_id = 73492 ON CONFLICT (game_id, language_code) DO NOTHING;
