INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('arcy-2', 18377, '1994-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/owytlxtwz80n1mt8tjeh.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcy 2', 'Arcy 2 is a VGA puzzle game that might remind you a little of Kroz. You play a smiley face who must collect all of the keys in a level before you can leave. Each enemy moves in a specific way, so the puzzle is figuring out how to move through the level without getting killed. Some enemies will only move if you cross their path, some will kill you instantly, some move in straight lines and only turn left or right, and some will try to trap you. Rocks can be used to interpose something between yourself and your enemies, and sometimes must be used to destroy walls or barriers. The soundtrack gets old quickly (one stanza of "The Entertainer" plays in a loop forever), but the game is very challenging and should entertain anyone who is up to the challenge. There are 3 volumes in this game, with only the first volume playable in the shareware version.' FROM games WHERE igdb_id = 18377 ON CONFLICT (game_id, language_code) DO NOTHING;
