INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jetstrike', 'Fasten your seatbelts and get ready to play JETSTRIKE - the number one flight action game from Rasputin. Amazing new 24-bit graphics; A simplified control system (so anyone can play); A huge, specially composed CD soundtrack; Nearly 200 missions, many unique to this version; Multiplayer option for between 2 and 8 opponents; Over 60 different aircraft to choose from; 60 weapons systems (there''s even a nuclear bomb!)' FROM games WHERE igdb_id = 37108 ON CONFLICT (game_id, language_code) DO NOTHING;
