INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'IMG International Tour Tennis', 'Licensed by the International Management Group (IMG), this rare Electronic Arts venture into Tennis features 32 professional players (all male and licensed by the IMG) including Bjorn Borg, Marcelo Rios, Patrick Rafter and Yevgeni Kafelnikov in 15 tournaments with different surfaces. Game modes include exhibition, tour and tournament for both singles and doubles.
