INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raiden DX', 'Vertical scrolling shoot-em-up that adds new features to its prequel Raiden II. Choose from three separate missions: Training special stage, Alpha levels 1-5 and Bravo levels 1-9. Collect various power-ups to increase your weaponry. Lots of secrets and bonuses including ratings based upon player performance' FROM games WHERE igdb_id = 8857 ON CONFLICT (game_id, language_code) DO NOTHING;
