INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubsy in Fractured Furry Tales', 'Bubsy in: Fractured Furry Tales was released December 15, 1994 for the Atari Jaguar. This title sets Bubsy traversing across various fairy tales. The game sees Bubsy taking on the Mad Hatter in Alice in Wonderland, the Giant in Jack and the Beanstalk, the Djinni in Ali Baba and the 40 Thieves, a sea monster in Twenty Thousand Leagues Under the Sea and Hansel and Gretel in Candyland. The game plays similarly to the prior two games in the series, but without any of the gadgets or band-aids of Bubsy 2.' FROM games WHERE igdb_id = 7805 ON CONFLICT (game_id, language_code) DO NOTHING;
