INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daze Before Christmas', 'In Daze Before Christmas, you''re Santa. According to the game''s Christmas calender, you have 24 areas to explore such as factories, workshops, caves, and more. Each area is filled with nasty enemies like penguins, jack-in-the-boxes, helicopters, snowmen, and many others. Furthermore, after every five areas, Santa has to come face-to-face with not only The Evil Snowman, The Timekeeper, and Louse the Mouse, but also Mr. Weather.' FROM games WHERE igdb_id = 7662 ON CONFLICT (game_id, language_code) DO NOTHING;
