INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Man 2: The New Adventures', 'Pac-Man 2: The New Adventures, known in Japan as Hello! Pac-Man, is a side-scrolling adventure game "sequel" to Pac-Man. Instead of being a maze game like the majority of its predecessors, Pac-Man 2 incorporates light point-and-click adventure game elements. It was produced and published by Namco for the Super Nintendo Entertainment System (SNES) and Sega Mega Drive/Genesis systems, and was released on April 6, 1994 by Namco. The game borrows its structure and certain elements from Pac-Land, and also appears to contain certain elements from the animated series, such as Pac-Man''s family and a main villain commanding the ghosts. The Genesis version was not released in Japan or Europe.' FROM games WHERE igdb_id = 11603 ON CONFLICT (game_id, language_code) DO NOTHING;
