INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alert X: Ostatnia Nadzieja Ziemi', 'Alert X is a classic side-scrolling space shooter, set in 2001 year, when an alien race invaded Earth. As a space fighter pilot the player must defeat waves of enemies, coming from each side of the board. The figure may be moved in each direction and have unlimited ammo. Each contact with an enemy unit or missile takes a large amount of energy, causing a quick destruction.' FROM games WHERE igdb_id = 14237 ON CONFLICT (game_id, language_code) DO NOTHING;
