INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dyna Gears', 'Dyna Gear: An Action Adventure On The Era Of Dinosaur is a 2D arcade platform game. The player can choose from two characters - Roger and Wolf. Gameplay is fast and simple - just run left and shoot enemies. Heroes can use various weapons, like swords, flails or arrows. The world in Dyna Gear: An Action Adventure On The Era Of Dinosaur is full of dinosaurs and various strange creatures.' FROM games WHERE igdb_id = 39709 ON CONFLICT (game_id, language_code) DO NOTHING;
