INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cannondale Cup', 'Choose from 1 of 8 different racers who compete on 8 different bicycle race courses. The game splits the courses into different stages, with each stage having a requirement to move on to the next stage. The requirements are based on completing a set number of laps or attaining a certain score, except for the final race where the player must come in 1st place in 30 laps.
