INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Airlines', 'The main object of the game was to successfully set up an airline by buying aircraft, planning routes, setting ticket prices and dealing with events such as hostage and oil crises. The game had 4 airlines, a minimum of one of which was human controlled, with the rest being computer-controlled. The game begins with the year set as 1970 and as time progresses more aircraft models become available, corresponding with their first flights in reality.' FROM games WHERE igdb_id = 87752 ON CONFLICT (game_id, language_code) DO NOTHING;
