INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rapid Deployment Force: Global Conflict', 'RDF (Rapid Deployment Force) is a first-person 3D tank shooter with the player going up against a plethora of enemies including other tanks, missile launchers, helicopters among many others. The player can use either their 120mm cannon or their laser-guided missiles in a variety of locations that including the Eastern European countryside to the Alaskan Tundra. The story is told through FMV clips' FROM games WHERE igdb_id = 46606 ON CONFLICT (game_id, language_code) DO NOTHING;
