INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Race Track', 'Race Track is a Windows shareware version of the classic Swiss racing simulation game. Not an arcade game, but just as exciting—it requires thinking rather than reflexes. A good example of a game based on simple rules that models the real world with amazing accuracy. Design and build your own tracks and share them with a friend. Race against a friend or the ''ghost'' of the track champion. Challenging but fun, easy to learn and play, great graphics, sound effects, and MIDI background music!' FROM games WHERE igdb_id = 93275 ON CONFLICT (game_id, language_code) DO NOTHING;
