INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Royal Flush', 'Royal Flush is a simulation of the real life pinball machine of the same name by Gottlieb. The main focus lies on a realistic feeling and the ball physics. The game is played with just four buttons: two to handle the two paddles, one to release the balls, and one to simulate the shaking on a real pinball machine.' FROM games WHERE igdb_id = 79182 ON CONFLICT (game_id, language_code) DO NOTHING;
