INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panic in Nakayoshi World', 'This title is about monsters that are attacking the World of Nakayoshi. The monsters are eating up the citizens. The more they eat, the hungrier they get. Four girls must stop the monsters and defeat Daima to save the World of Nakayoshi. The game is an overhead Adventures of Lolo-style puzzle game featuring characters from various Nakayoshi-printed manga. Sailor Moon and Chibi Moon are playable characters. There are also characters from Goldfish Warning!.' FROM games WHERE igdb_id = 42374 ON CONFLICT (game_id, language_code) DO NOTHING;
