INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Journey to the West', 'The Journey to the West tells the story of the fourteen-year pilgrimage of the monk Xuanzang, one of China’s most famous religious heroes, and his three supernatural disciples, in search of Buddhist scriptures. Throughout his journey, Xuanzang fights demons who wish to eat him, communes with spirits, and traverses a land riddled with a multitude of obstacles, both real and fantastical. An adventure rich with danger and excitement.' FROM games WHERE igdb_id = 46927 ON CONFLICT (game_id, language_code) DO NOTHING;
