INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pickle Wars', 'Pickle Wars is an MS-DOS platform game created in 1993 by Karen Crowther through Redwood Games and published by MVP Software. A planet gets invaded by pickles. The player (alternating between playing a man and a woman) goes on a journey to find hidden weapons. The player needs to collect all the SaladShooters in the level to pass through the exit door. The player can then shoot salad at the aliens, and the aliens will faint. Junk food and pickles are collectible for points, and carrots are for health.' FROM games WHERE igdb_id = 93466 ON CONFLICT (game_id, language_code) DO NOTHING;
