INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vasteel-2', 54921, '1994-07-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4r0b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scgzud.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vasteel 2', 'The sequel to the epic mecha war strategy title Vasteel. The sequel is more story-heavy than its predecessor, and has more clearly pronounced anime/manga aesthetics. Animated cut scenes occur between the missions and advance the story. Even during the large strategic battles, characters would often engage in dialogue, and scripted events might occur. The gameplay also underwent some changes. Vasteel 2 is, like its predecessor, a hex-based, turn-based strategy game with robotic combat; however, the action sequences are gone, and the battles now proceed automatically, as in most games of this genre. Robot production and financial management were also simplified or removed. However, the player can choose to use various types of weapons before engaging an enemy in combat. For example, robots can use melee attacks, bipedal tanks can use different laser beams, etc.' FROM games WHERE igdb_id = 54921 ON CONFLICT (game_id, language_code) DO NOTHING;
