INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yoshi no Cookie: Kuruppon Oven de Cookie', 'Yoshi no Cookie: Kuruppon Oven de Cookie is a cuisine focused re-release of the original Yoshi''s Cookie, exclusively for the Super Famicom. While the gameplay is identical, the game also adds cooking advice and recipes concerning the Kuruppon Oven from Panasonic. Only 500 copies were released in Japan, and the game was not available in other territories. It currently fetches a very high price on the Japanese retro game market.' FROM games WHERE igdb_id = 37755 ON CONFLICT (game_id, language_code) DO NOTHING;
