INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kenyuu Densetsu Yaiba', 'Based on the anime series of the same name, juvenile samurai Yaiba Kurogane goes on an adventure across Japan while trying to learn the secrets of his sword. The game is made up of mainly platforming levels, with a few instances of runner levels and story-based cutscenes between every part that makes up the level.' FROM games WHERE igdb_id = 282499 ON CONFLICT (game_id, language_code) DO NOTHING;
