INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Realms of Despair', 'Realms of Despair is the original Smaug MUD - an interactive multiplayer medieval adventure game - and is free to play. We have an active role playing community, an active player-killing (deadly) community, and a very active peaceful community. Players can choose from 13 classes - including one deadly-only class - and 14 races. Character appearances can be customized on creation, and we have a vast collection of equipment that is level, gender, class, race and alignment specific.' FROM games WHERE igdb_id = 127951 ON CONFLICT (game_id, language_code) DO NOTHING;
