INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild Cup Soccer', '"Wild Cup Soccer" is an isometric viewpoint, with a number of vicious moves are on offer, even tackles Vinnie Jones would flinch at along with lethal head-butts and shoulder barges. If a game finishes drawn, it goes into a ''Penalty Shoot Out'', which involves going round shooting the opposition; the last team standing wins. The pre-match screens include attacking at defensive play styles, transfers and the chance to buy items such as rocket launchers and shields.' FROM games WHERE igdb_id = 38841 ON CONFLICT (game_id, language_code) DO NOTHING;
