INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Attack of the Zolgear', 'Attack of the Zolgear is an arcade game for one to six players released by Namco. It is a sequel to Galaxian3. This game used two LaserDisc players simultaneously for the outer space background, while computer generated graphics were overlaid on top. The environmental "theater" used for Galaxian 3 received this upgraded sequel in 1994.' FROM games WHERE igdb_id = 58775 ON CONFLICT (game_id, language_code) DO NOTHING;
