INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zunzunkyou-no-yabou', 40972, '1994-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/z8t35n0b7s1t8gzkpsbo.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zunzunkyou No Yabou', 'ZnY is basically Parodius meets Space Invaders (a premise also done by Taito themselves with Space Invaders ''95: Attack of the Lunar Loonies), except you control a statue instead of a spaceship and you fight within an enclosed arena instead of vertical space. It would be more akin to an arena shooter like Robotron: 2084, except your statue can only shoot straight upward. The stages themselves all seem to be themed around different parts of the world: The kabuki boss on the far-left represents Japan, the chef represents China and mainland Asia, the crusader knight stands for Europe, and the superhero on the far-right stands for America. Yet even outside of the Japanese stages, there''s a distinctly goofy flair about the game that emphasizes screwy cultural stereotypes from a Japanese game company. The game''s actual developer, Minato Giken, also helped work on the Game Gear version of Dynamite Headdy, one of the most fantastically insane Genesis platformers ever, and that same sort of unhinged design can also be seen in ZnY. You fight talk show hosts, salarymen, pandas, matadors, clowns, rock stars, and other outlandish opponents detailed in exaggeratedly comical fashions. The graphic design is definitely ZnY''s strong suit, with its colorful characters and quite detailed playfields making high use of Sega''s System C-2 hardware, the same processor behind Puyo Puyo.' FROM games WHERE igdb_id = 40972 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 40972 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
