INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leading Jockey', 'Leading Jockey is a horse racing game for the Super Famicom. It focuses more on the racing aspect than the simulation/management of one''s horses and jockeys, unlike ASCII''s Derby Stallion or Hect''s Thoroughbred Breeder. The player still has a number of options when setting up a race to appeal to enthusiasts of the sport.' FROM games WHERE igdb_id = 38108 ON CONFLICT (game_id, language_code) DO NOTHING;
