INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1000 Miglia: Great 1000 Miles Rally', 'A driving game with top-down pseudo 3-D graphics. You can select one of ten cars and depending upon which vehicle has been chosen, you can select the starting point of the race. The game can be installed in a variety of cabinets using either a joystick and buttons or a steering wheel and foot pedals for control.' FROM games WHERE igdb_id = 39354 ON CONFLICT (game_id, language_code) DO NOTHING;
