INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Compton''s Interactive Encyclopedia', 'CIE Sega CD captures the imagination and inspires the mind - all from the convenience of your television screen. With the simple click of the arrow key, you can take a ride through history. Visit the farthest corner of the globe, share the mystery and majesty of the wild kingdom, and explore the vast reaches of outer space. The articles of the complete 26 volumes of Compton''s Encyclopedia plus pictures, sounds, movies, and slide-shows are now available in CIE Sega CD!' FROM games WHERE igdb_id = 306581 ON CONFLICT (game_id, language_code) DO NOTHING;
