INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario''s Early Years! Fun with Numbers', 'Mario''s Early Years! Fun with Numbers is an educational Mario game that taught numbers and basic geometry to children. The game takes place on a set of islands to which Mario and Princess Peach sail. The player can click one of the islands to enter, after which the player sees Luigi asleep. Once the player clicks him, various activities must be performed to learn. Activities include counting objects, identifying shapes, comparing sizes, and sorting.' FROM games WHERE igdb_id = 42501 ON CONFLICT (game_id, language_code) DO NOTHING;
