INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Greatest Heavyweights', 'Eight World Heavyweight Champs Answer the Bell in this ultimate showdown to decide who''s #1! Muhammad Ali, Jack Dempsey, Joe Frazier, Larry Holmes, Evander Holyfield, Joe Louis, Rocky Marciano, and Floyd Patterson - all in their prime and looking for knockouts! Each Champion looks and boxes in their signature styles. It''s Ali''s speed against Marciano''s power, Holmes'' stinging jab versus Frazier''s devastating hook!' FROM games WHERE igdb_id = 45783 ON CONFLICT (game_id, language_code) DO NOTHING;
