INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Okamoto Ayako to Match Play Golf', 'Okamoto Ayako to Match Play Golf (sometimes "Okamoto Ayako to Match Play Golf: Ko Olina Golf Club in Hawaii") is a 1994 golf simulator exclusive to the Japanese Super Famicom. It features the likeness and is endorsed by professional golfer and LPGA (Ladies Professional Golf Association) champion Ayako Okamoto, and is one of a handful of sports games to be endorsed by a female athlete. The game uses the real-life golf course of Ko Olina Golf Club in Hawaii. Ko Olina hosted the LPGA Hawaiian Open between 1990-95, when this game was developed.
