INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'İstanbul Efsaneleri: Lale Savaşçıları', 'İstanbul Efsaneleri: Lale Savaşçıları (Legends of Istanbul: Tulip Warriors) is the first Turkish fantasy role playing game. Designed in a funny and comical style, the game is set in an alternate Istanbul. The language of the game is Turkish. It was first published for Amiga and PC platforms in years 1994 and 1997, respectively, and a revival gold edition was published later in 2005 to make it work under newer operating systems using DOS emulators.
