INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armored Fist', 'Armored Fist offers realistic armored warfare in numerous tactical theaters. The player can choose from an extensive line-up of modern-day armored vehicles utilized by U.S. forces, in addition to those commonly used by Soviet troops. The game was one of the earliest tank sims to offer a mission editor with broad capabilities. Six linear campaigns are offered in addition to a training campaign.' FROM games WHERE igdb_id = 14983 ON CONFLICT (game_id, language_code) DO NOTHING;
