INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fray in Magical Adventure CD: Xak Gaiden', 'Fray is a young girl whom Latok has saved during the events of Xak. Fray falls in love with Latok and decides to prove him that she can be more than just a damsel in distress. She studies magic in a university for three years and afterwards begins a long journey to find Latok and to help him in his battle against evil.' FROM games WHERE igdb_id = 65273 ON CONFLICT (game_id, language_code) DO NOTHING;
