INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Heroes', 'Far away in the Aotis continent, a powerful sword exists, imbued with magic. People there all have unimaginable power, so it attracts lots of warriors. Now, the best warriors - Rex, Malcolm, Roger, Big Whale, Daphne, Ned, Rock Tiger and Dark Moon - get together for a race. However, there is some scheming behind the race...' FROM games WHERE igdb_id = 48567 ON CONFLICT (game_id, language_code) DO NOTHING;
