INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bowmen', 'Bowmen followed the trend that began in the early 90s of offering simple games with nude images, although in this case with naively “spicy” scenes. Released in 1994, it is a psychedelic game of skill, in which the story of a somewhat “peeping tom” boy, who is converted into a kind of angel by divine grace, is shown as an introduction.' FROM games WHERE igdb_id = 277383 ON CONFLICT (game_id, language_code) DO NOTHING;
