INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mighty Morphin Power Rangers', 'In this version of Mighty Morphin Power Rangers, the player has three basic attacks (one of which is accomplished by pressing the two action buttons simultaneously), a throw, and three special moves per character. The game consists of three game modes: a single-player story game which features a series of plot-based battles against an assortment of enemies, a single-player vs. game, and a two-player Link game in which two players battle each other using the link cable.' FROM games WHERE igdb_id = 75979 ON CONFLICT (game_id, language_code) DO NOTHING;
