INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peanuts: Yearn 2 Learn', 'Yearn2Learn: Peanuts is edutainment software for kids aged 3 to 10, hosted by Snoopy and the Peanuts gang. It includes a series of independent activities such as a math game, a geography game, a reading game (which consists of animated Peanuts strips), a visual coordination game and an electronic coloring book. The game features full voice-overs explaining every feature in it and also spelling words and locations. Additionally, the game has many "hotspots" which trigger animations, sounds, etc. Developed and published by Image Smith.' FROM games WHERE igdb_id = 45890 ON CONFLICT (game_id, language_code) DO NOTHING;
