INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hotel Mario', 'Hotel Mario is a puzzle/platformer game who takes place in hotels. The general goal in each stage is to close all the doors on every floor. However, various enemies will interfere and reopen them at times. Elevators are needed to travel between floors. The first six hotels have ten stages, whilst the seventh has fifteen. The game had low sales partially due to a lack of interest in the CD-i system, and received mainly poor reviews.' FROM games WHERE igdb_id = 8535 ON CONFLICT (game_id, language_code) DO NOTHING;
