INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WCW SuperBrawl Wrestling', 'WCW SuperBrawl Wrestling is a professional wrestling video game published by FCI, Inc. for the Super Nintendo Entertainment System in 1994. The third World Championship Wrestling (WCW) video game, it is named after the pay-per-view SuperBrawl. It was the only WCW game to be released on the Super NES, and the last to be produced by FCI, Inc. A Sega Genesis version was planned but never released.' FROM games WHERE igdb_id = 38404 ON CONFLICT (game_id, language_code) DO NOTHING;
