INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Simpsons: Bart & the Beanstalk', 'Once upon a time... Bart Simpson had a cow, man. He traded it for some magic beans which grew into a giant beanstalk. If he can scale the stalk, overcome giant bugs, mash monstrous mice, and grab the Giant''s loot, he''ll become a zillionaire faster than you could say "I DIDN''T DO IT!"' FROM games WHERE igdb_id = 2837 ON CONFLICT (game_id, language_code) DO NOTHING;
