INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'U.S. Navy Fighters', 'U.S. Navy Fighters is a video game developed and published by Electronic Arts for the PC. An expansion pack, Marine Fighters, was released in 1995. U.S. Navy Fighters: Gold was also released in 1995, it is a compilation package that includes both the main game and the expansion. U.S. Navy Fighters is a forerunner to Jane''s Combat Simulations series. An updated version, Jane''s US Navy Fighters 97, was released in 1996 for Microsoft Windows and is officially part of the series.' FROM games WHERE igdb_id = 79890 ON CONFLICT (game_id, language_code) DO NOTHING;
