INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sesame Street Counting Cafe', 'Counting Cafe is an educational game based on the popular children''s show Sesame Street. The player controls Grover, working as a waiter at a restaurant, where Mr. Johnson appears and orders various items. The player must take Grover into the kitchen, collect the items ordered, and return to Mr. Johnson''s table, where he will reward the player with a star if the order is correct. If the player picks up the wrong items, they can be taken to Cookie Monster at the back of the restaurant, who will eat them and clear Grover''s tray.' FROM games WHERE igdb_id = 46198 ON CONFLICT (game_id, language_code) DO NOTHING;
