INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AIDS Awareness', 'AIDS Awareness contains 100 questions to test your awareness of the facts about HIV and AIDS. You won''t know all of the answers-- in fact, many of the questions are very difficult. As you select your answers, the program will tell you whether you are right or wrong, and it will tell you why. By the time you''ve answered all of the questions, you will be AIDS Aware.' FROM games WHERE igdb_id = 260803 ON CONFLICT (game_id, language_code) DO NOTHING;
