INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sansan', 45609, '1994-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xnc.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sansan', 'Sansan (サンサン) is an online service allowing people living in Japan to play the abstract strategy board game Go with other subscribers over the internet on a Windows PC. However, at its launch in 1994, a version for the Sega Mega Drive was also made available. This version of the game allows players who have a Sega Mega Modem to connect over a 33.3kbps or ISDN line to play other members who have a Sansan ID. However, as of 2011, there are no known Mega Drive-compatible Sansan servers. A local two-player version of the game is also included for play. 
