INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyper Pac-Man', 'This is an updated version of Namco''s "Pac-Man", featuring forced-perspective 3-D graphics that allow the players to jump over the enemy ghosts; in a similar fashion to Namco''s "Pac-Mania", released in 1987. There are secret items and food to be found on each level that increases the player''s power and score. For extra bonus stages, complete a level without eating any of the power dots.' FROM games WHERE igdb_id = 39806 ON CONFLICT (game_id, language_code) DO NOTHING;
