INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Der Planer', 'In Der Planer, you are the boss of a forwarding business. You not only have to plan the best and cheapest routes between the different cities, but also need to acquire drivers, trucks (or planes, train space...), get customs papers, and last but not least, make your family happy, too.' FROM games WHERE igdb_id = 86048 ON CONFLICT (game_id, language_code) DO NOTHING;
