INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dolucky no Puzzle Tour ''94', 'This video game is a puzzle block fighter similar to other Japanese block games on the Super Famicom like Dossun! Ganseki Battle. The player has to match coloured blocks together and gain combos/special blocks to fight against its opponent. The game features stylized "muted" graphics and a soundtrack composed by Hideyuki Shimono and Akihito Ohkawa. This was their first collaboration before Zero Divide in 1995.' FROM games WHERE igdb_id = 38131 ON CONFLICT (game_id, language_code) DO NOTHING;
