INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mutant Rampage: Bodyslam', 'Civilization is in decay. Teams of bionic warriors rule the ravaged capitals of the world. But now a human challenge has been issued - YOU! Only you have the speed and skill to beat the mutants and triumph in MUTANT RAMPAGE! Face ten mutant teams in ten ravaged cities around the world. Expect to be taunted and teased by in-your-face foes in full-screen digital video animation.' FROM games WHERE igdb_id = 45912 ON CONFLICT (game_id, language_code) DO NOTHING;
