INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Totsugeki! Mix', 'Totsugeki! Mix is a cute action platform game. Choosing one of the three girls, each with their own unique weapon, the player must travel through ten different stages fighting Galuf''s unreasonably cute army. There are several different special magic powers that can be collected, including a fairy familiar, magic shield, and time slow, and a boss waits at the end of each stage.' FROM games WHERE igdb_id = 213551 ON CONFLICT (game_id, language_code) DO NOTHING;
