INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LineWars II', 'LineWars II is a 3D space combat simulation game that was released as shareware in 1994. Created by Patrick Aalto and published by Safari Software, a division of Epic MegaGames, the game draws inspiration from titles like Wing Commander and Elite, focusing on combat rather than trading. The shareware version offered a demo, a few single-player missions, and multiplayer support for up to 8 players via modem or network. The full registered version expanded upon this with additional single-player missions and multiplayer modes.' FROM games WHERE igdb_id = 69230 ON CONFLICT (game_id, language_code) DO NOTHING;
