INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metamoqester', 'Metamoqester (known in Japan as "Oni: The Ninja Master") is a 2D arcade fighting game, similar in concept to Red Earth or Monster Maulers. One or two players (there is a co-op mode) fight against big monsters in deadly duels. There are three different characters to choose from. The game uses four buttons - Weak Attack, Medium Attack, Strong Attack, and Shoot/Throw Weapon.' FROM games WHERE igdb_id = 39542 ON CONFLICT (game_id, language_code) DO NOTHING;
