INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vid Grid', 'Vid Grid is a tile-matching full motion video puzzle game originally developed by Geffen Records and published by Jasmine Multimedia Publishing for Windows on September 13, 1994. It was later ported to the Atari Jaguar CD by High Voltage Software in 1995, where it was included alongside with Blue Lightning as one of the pack-in games for the peripheral when it launched. It is the first entry in the franchise of the same name.
