INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My First Encyclopedia', 'Set inside a beautifully designed and interactive tree, My First Encyclopedia is a collection of over 575 different entries. Each entry is activated by a single click letting children see a word with a video explanation of each object. Animations, sound effects, and over an hour of original music add to this stimulating environment for play and learning. Real Kids, live action children who guide the user towards new learning discoveries, create a visually dynamic and magical place filled with over 50 activities and puzzles.' FROM games WHERE igdb_id = 143571 ON CONFLICT (game_id, language_code) DO NOTHING;
