INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NebulasRay', 'NebulasRay (ネビュラスレイ Nebyurasurei?) is a vertical scrolling shooter arcade game that was released by Namco in 1994 (but was first referred to, in the Katakana syllabic writing system of the Japanese language, in the ending for Tinkle Pit in 1993); it runs on the company''s NB-1 hardware, and the players assume control of two spaceships called the "Fighting Rays" (red for Player 1, blue for Player 2), through six areas (Exeo, Evergrenes, Lost Marinarc, Sandvurn, Stream Drive, and Master Fortress), along with an "extra" one called the "Challenging Area" (which is the same as the first one, but the players will only have one life to get through it, for their remaining lives will have been added to their scores, after defeating the sixth area''s boss). Nebulas Ray has many 3-D elements and very detailed graphics.' FROM games WHERE igdb_id = 39715 ON CONFLICT (game_id, language_code) DO NOTHING;
