INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castle of the Winds 2', 'Castle of the Winds is a two part graphical adventure game, loosely based on fantasy role playing games, and drawing much inspiration from Norse mythology. Part two concerns the character''s efforts to fulfill his or her destiny. To do this, the character must defeat Surtur and recover the stolen Helm of Storms from his possession. Along the way, of course, he or she will be opposed by deadly monsters and traps, but will find treasure and enchanted objects to aid his or her quest.' FROM games WHERE igdb_id = 14447 ON CONFLICT (game_id, language_code) DO NOTHING;
