INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('midnight-stranger', 143102, '1994-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ryo.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Stranger', 'Midnight Stranger (1994) is the first of two published interactive multimedia CD-ROM based collaborations between writer and director Jeff Green and the Animatics Multimedia Corporation. Noted for its cinéma vérité style, it is a Point Of View (POV) video-based experiment in simulated socializing that takes place in an anonymous city late one night. Players navigate between several locations, and can interact with one or more people in each location to varying effects based on the player''s "reactions" to that person. The main technical innovation of Midnight Stranger is its use of an emotional continuum Mood Bar for interaction with the in-story characters rather than a text interface or an itemized set of options for each interaction. The Mood Bar simulates some of the frustration and uncertainty when dealing with other people in social situations, and provides a more realistic role playing experience' FROM games WHERE igdb_id = 143102 ON CONFLICT (game_id, language_code) DO NOTHING;
