INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('al-qadim-the-genie-s-curse', 2418, '1994-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co26eb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar58ay.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Al-Qadim: The Genie''s Curse', 'Al Qadim: The Genie''s Curse features a new and improved interface and game engine. The perspective is that of a slant-overhead view that allows you to guide your character through the adventure. In comparison the view and scrolling are much better than those of Ultima series. The game as based on the AD&D 2nd Edition rules and is enriched by exiting new concepts, spells, and creatures designed especially for this campaign setting. You play a single fighter type character. Swordplay is enhanced to a semi-arcade level with an ability to learn up to three specific combat moves.
